// Só conversas individuais seguem para o painel; quem pode dar ordens é decidido lá.
const INVISIVEL = '\u2063';
const NAO_E_MENSAGEM = /reaction|protocol|senderkey|edited|poll|sticker/i;
const saida = [];
for (const item of $input.all()) {
  const corpo = item.json.body ?? item.json;
  const dados = corpo.data ?? {};
  const chave = dados.key ?? {};
  const remoto = String(chave.remoteJid ?? '');
  if (!remoto || /@(g\.us|broadcast|newsletter)$/.test(remoto)) continue;
  const chat = [chave.remoteJidAlt, chave.senderPn, chave.remoteJid]
    .map((v) => String(v ?? ''))
    .find((v) => v.endsWith('@s.whatsapp.net'));
  if (!chat) continue;
  const m = dados.message ?? {};
  const texto = m.conversation || m.extendedTextMessage?.text || '';
  const legenda = m.imageMessage?.caption || m.documentMessage?.caption || m.videoMessage?.caption || '';
  // resposta do próprio cérebro: sem este descarte o chat "Você" entraria em laço
  if (texto.startsWith(INVISIVEL) || legenda.startsWith(INVISIVEL)) continue;
  const tipoBruto = String(dados.messageType ?? '');
  const tipo = texto ? 'texto' : /audio/i.test(tipoBruto) ? 'audio' : 'outro';
  if (tipo === 'outro' && NAO_E_MENSAGEM.test(tipoBruto)) continue;
  saida.push({ json: { texto, tipo, deMim: Boolean(chave.fromMe), chat, eu: String(corpo.sender ?? '') } });
}
return saida;
